import{_ as a,o as s,c as n,aO as t}from"./chunks/framework.vjUPZZJn.js";const h=JSON.parse('{"title":"systemd 强杀服务导致配置文件损坏的排查","description":"","frontmatter":{"date":"2026-10-08T20:10:00.000Z","title":"systemd 强杀服务导致配置文件损坏的排查","source":[["1-知识/问题记录/parameter.json 文件损坏排查"]],"tags":["工具","问题排查","systemd"],"categories":["工具"],"permalink":"/pages/ff1c5c"},"headers":[],"relativePath":"工具/systemd 强杀服务导致配置文件损坏的排查.md","filePath":"工具/systemd 强杀服务导致配置文件损坏的排查.md","lastUpdated":1791440489000}'),r={name:"工具/systemd 强杀服务导致配置文件损坏的排查.md"};function l(o,e,i,p,d,c){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="systemd-强杀服务导致配置文件损坏的排查" tabindex="-1">systemd 强杀服务导致配置文件损坏的排查 <a class="header-anchor" href="#systemd-强杀服务导致配置文件损坏的排查" aria-label="Permalink to &quot;systemd 强杀服务导致配置文件损坏的排查&quot;">​</a></h1> <p>一个由 systemd 托管的后台服务，重启后读到了自己损坏的 JSON 配置文件，无法启动。本文记录这次排查的完整过程：从报错日志确认文件损坏，复盘出两个损坏场景——直接断电，以及 systemd 停机超时后强杀进程导致写入中断，最后给出退出顺序与原子写入两个修复方向。对任何「服务退出时要落盘配置」的场景都适用。</p> <h2 id="现象" tabindex="-1">现象 <a class="header-anchor" href="#现象" aria-label="Permalink to &quot;现象&quot;">​</a></h2> <p>参数服务启动时报错，配置文件 <code>parameter.json</code> 解析失败：</p> <div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[2026-05-27 16:20:34.254] [error] JSON parse failed: [json.exception.parse_error.101] parse error at line 1, column 1: syntax error while parsing value - unexpected end of input; expected &#39;[&#39;, &#39;{&#39;, or a literal</span></span>
<span class="line"><span>[2026-05-27 16:20:34.254] [error] /opt/controller/cfg/parameter.json, Json file has duplicate keys.</span></span>
<span class="line"><span>[2026-05-27 16:20:34.254] [error] Failed to load parameter file: &#39;/opt/controller/cfg/parameter.json&#39;</span></span>
<span class="line"><span>[2026-05-27 16:20:36.244] [warning] Cannot save to JSON: JSON data is empty.</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="根因分析" tabindex="-1">根因分析 <a class="header-anchor" href="#根因分析" aria-label="Permalink to &quot;根因分析&quot;">​</a></h2> <p>启动时读到损坏的配置文件，初始化失败。参数服务随后尝试把内存中的参数落盘，但此时参数列表为空，打印 <code>Cannot save to JSON: JSON data is empty.</code> 后直接返回，没有执行写文件操作。</p> <p>结合 <code>JSON parse failed</code> 的报错判断：文件不为空，但内容是不完整的 JSON——上一次退出时写了一半。问题从「这次为什么起不来」转化为「上次退出时谁打断了写入」。</p> <h2 id="损坏是怎么发生的" tabindex="-1">损坏是怎么发生的 <a class="header-anchor" href="#损坏是怎么发生的" aria-label="Permalink to &quot;损坏是怎么发生的&quot;">​</a></h2> <h3 id="场景一-直接断电" tabindex="-1">场景一：直接断电 <a class="header-anchor" href="#场景一-直接断电" aria-label="Permalink to &quot;场景一：直接断电&quot;">​</a></h3> <p>断电瞬间配置文件正在写入，页缓存来不及刷盘，文件内容截断为不完整的 JSON。这个场景没有优雅退出流程可走，只能靠写入方式本身兜底（见文末原子写入）。</p> <h3 id="场景二-systemd-停机超时强杀" tabindex="-1">场景二：systemd 停机超时强杀 <a class="header-anchor" href="#场景二-systemd-停机超时强杀" aria-label="Permalink to &quot;场景二：systemd 停机超时强杀&quot;">​</a></h3> <p>整套服务由一个 systemd 服务单元托管，<code>systemctl stop</code> 触发停止。systemd 按 <code>KillMode=mixed</code> 的规则执行停机：</p> <ol><li>向主进程发送 SIGTERM（信号 15），请求优雅退出</li> <li>等待最多 <code>TimeoutStopSec</code>（该单元配置为 5s；不配置时默认 90s）</li> <li>超时后向控制组内所有残留进程发送 SIGKILL（信号 9）</li></ol> <p>这个单元的主进程是一个服务管理进程，它收到 SIGTERM 后的设计流程是：先回收自身资源，再向各业务服务发送退出信号，等待 2s，最后调用 <code>sync()</code> 强制落盘。</p> <p>实际日志显示，它自身的资源回收花了接近 5s。等它开始给业务服务发退出信号时，systemd 的超时窗口已经用完，控制组内所有进程直接被 SIGKILL 强杀，业务服务的配置写入被中断：</p> <div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[15:32:41.048] 收到 SIGTERM，开始资源回收</span></span>
<span class="line"><span>[15:32:43.023] 第一个子模块回收完成（~2s）</span></span>
<span class="line"><span>[15:32:44.449] 采集服务回收完成（~1.4s）</span></span>
<span class="line"><span>[15:32:45.969] 资源回收完毕，开始向业务服务发送退出信号   ← 距 SIGTERM 已过 ~5s</span></span>
<span class="line"><span>[~15:32:46]   systemd 超时，SIGKILL 强杀全部进程</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>从 SIGTERM 到开始发送退出信号耗时约 5s，业务服务没有时间完成退出和落盘，写到一半的配置文件就此留在磁盘上。</p> <h2 id="修复与预防" tabindex="-1">修复与预防 <a class="header-anchor" href="#修复与预防" aria-label="Permalink to &quot;修复与预防&quot;">​</a></h2> <p>三个方向，前两个针对本例根因，第三个针对排查过程中的盲区：</p> <ol><li><strong>退出顺序</strong>：管理进程应先向各业务服务发送退出信号，再做自身资源回收；或者压缩自身回收耗时，确保在 <code>TimeoutStopSec</code> 窗口内给业务服务留足安全退出的时间。停机窗口实在不够时，也可以直接调大 <code>TimeoutStopSec</code></li> <li><strong>原子写入</strong>：配置文件落盘用 write-to-temp + rename 模式——先写临时文件，写完并 <code>fsync</code> 后用 <code>rename()</code> 替换原文件。<code>rename</code> 在同一文件系统上是原子操作，无论进程在哪一步被杀，磁盘上的文件要么是旧版本、要么是完整的新版本，不会出现半截文件</li> <li><strong>让断电可观测</strong>：本例中直接断电的场景没有收到电源管理组件的异常上报，缺乏直接证据，只能靠日志推理。关键事件（断电、异常关机）有上报渠道，排查时能少走弯路</li></ol> <h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2> <ul><li>systemd 停机不是无限等待：<code>TimeoutStopSec</code> 超时后 SIGKILL 直接发给整个控制组，优雅退出流程必须在这个窗口内完成</li> <li>管理进程自身的清理逻辑会挤占被管理服务的退出时间；退出顺序上先通知别人，再收拾自己</li> <li>配置类文件一律用临时文件 + rename 的原子写入，把「写到一半被杀」从不可恢复变成无害</li></ul>`,43)])])}const u=a(r,[["render",l]]);export{h as __pageData,u as default};
